import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.DoCD98hS.js";const p=JSON.parse('{"title":"Ant Design · 多框架组件与 Pro 模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/antd.md","filePath":"modules/catalog/antd.md","lastUpdated":1795336342000}'),a={name:"modules/catalog/antd.md"};function c(n,e,l,i,s,u){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ant-design-·-多框架组件与-pro-模板" tabindex="-1">Ant Design · 多框架组件与 Pro 模板 <a class="header-anchor" href="#ant-design-·-多框架组件与-pro-模板" aria-label="Permalink to &quot;Ant Design · 多框架组件与 Pro 模板&quot;">​</a></h1><p>合并 Ant Design 系列的框架差异与 React Pro 模板接入说明；Vue 2、Vue 3 和 React 的导出能力分别列出。</p><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/comps-vue2-antd</code></td><td>Vue 2 + Ant Design Vue 与 Df 系列</td></tr><tr><td><code>@melt-js/comps-vue3-antd</code></td><td>Vue 3 + Ant Design Vue 基础示例</td></tr><tr><td><code>@melt-js/comps-react-antd</code></td><td>React Ant Design 与 Pro 配套 UI</td></tr><tr><td><code>@melt-js/comps-vue2-antd-pro</code></td><td>Vue 2 + Ant Design Vue 的图表、列表页部件与弹窗 / 加载插件（提供方）</td></tr><tr><td><code>@melt-js/tpl-react-admin-antd-pro</code></td><td>基于 ant-design-pro 完整示例的宿主</td></tr><tr><td><code>@melt-js/tpl-vue2-admin-antd-pro</code></td><td>基于 ant-design-vue-pro 的 Vue 2 后台宿主，通用组件走远程</td></tr></tbody></table><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>演示地址</th></tr></thead><tbody><tr><td><code>tpl-react-admin-antd-pro</code></td><td><a href="https://unpkg.com/@melt-js/tpl-react-admin-antd-pro/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-vue2-admin-antd-pro</code></td><td><a href="https://unpkg.com/@melt-js/tpl-vue2-admin-antd-pro/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>comps-vue2-antd-pro</code></td><td><a href="https://unpkg.com/@melt-js/comps-vue2-antd-pro/hel_dist/index.html" target="_blank" rel="noreferrer">组件调试页</a></td></tr><tr><td><code>demo-vue2-antd</code></td><td><a href="https://unpkg.com/@melt-js/demo-vue2-antd/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>demo-vue3-antd</code></td><td><a href="https://unpkg.com/@melt-js/demo-vue3-antd/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>demo-react-antd</code></td><td><a href="https://unpkg.com/@melt-js/demo-react-antd/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr></tbody></table><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td>Vue 2：<code>install</code> / <code>rules</code></td><td>全局注册与校验规则</td></tr><tr><td>Vue 2 Pro：<code>install</code></td><td>预加载后按 <code>Pro</code> 前缀把组件注册到宿主 Vue</td></tr><tr><td>React：<code>comps</code> 命名空间</td><td>当前包内只有脚手架示例 <code>TestExport</code>，留给后续 Pro 配套 UI 复用</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td>Vue 2：<code>DfEmpty</code> / <code>DfPageTitle</code> / <code>DfNavigation</code></td><td>Df 系列组件；排行榜 <code>TierRanking</code> 已迁往 <code>comps-vue2-meme</code></td></tr><tr><td>Vue 3：<code>App</code> / <code>HelloWorld</code></td><td>当前基础示例</td></tr><tr><td>React：<code>TestExport</code></td><td>包内仅此一个示例导出，不提供 Ant Design 组件</td></tr><tr><td>Vue 2 Pro：<code>ProChartCard</code> / <code>ProChartTrend</code> / <code>ProTrend</code> / <code>ProBar</code> / <code>ProMiniBar</code> / <code>ProMiniArea</code> / <code>ProMiniSmoothArea</code> / <code>ProMiniProgress</code> / <code>ProLiquid</code> / <code>ProRadar</code> / <code>ProRankList</code> / <code>ProTagCloud</code> / <code>ProTransferBar</code></td><td>基于 viser / @antv/data-set 的图表 13 项</td></tr><tr><td>Vue 2 Pro：<code>ProAvatarList</code> / <code>ProAvatarListItem</code> / <code>ProEllipsis</code> / <code>ProFooterToolbar</code> / <code>ProIconSelector</code> / <code>ProNoticeIcon</code> / <code>ProNumberInfo</code> / <code>ProStandardFormRow</code> / <code>ProTagSelect</code> / <code>ProArticleListContent</code> / <code>ProTree</code> / <code>ProGlobalSearch</code> / <code>ProLimitTextArea</code> / <code>ProGallery</code> / <code>ProPageLoading</code></td><td>页面级部件，可脱离宿主 store 使用</td></tr><tr><td>Vue 2 Pro：<code>dialogPlugin</code> / <code>pageLoadingPlugin</code></td><td>对应原 <code>components/Dialog</code>、<code>components/PageLoading</code> 的插件入口</td></tr></tbody></table><h2 id="接入方式" tabindex="-1">接入方式 <a class="header-anchor" href="#接入方式" aria-label="Permalink to &quot;接入方式&quot;">​</a></h2><p>最小示例为 <code>demo-vue2-antd</code>、<code>demo-vue3-antd</code> 和 <code>demo-react-antd</code>。不能由系列名称推断三个框架具有同一套组件。</p><p>Vue 2 Pro 一组的参考模板是 <code>tpl-vue2-admin-antd-pro</code>：<code>main.js</code> 绑定 Vue 运行时并预加载 <code>comps-vue2-antd-pro</code>（<code>requiredExports</code> 校验 <code>ProChartCard</code> / <code>ProMiniArea</code> / <code>ProTagSelect</code> / <code>ProEllipsis</code> / <code>ProAvatarList</code> / <code>ProArticleListContent</code>），配合 <code>needCompsAutoInstall: true</code> 与 <code>vue: Vue</code> 完成全局注册，路由就绪后才挂载；页面从 <code>@/components</code> 导入。<code>comps-vue2-antd-pro</code> 的公开名称统一带 <code>Pro</code> 前缀，模板标签使用 <code>&lt;pro-chart-card&gt;</code> 这类写法，宿主不要再按上游原名（<code>ChartCard</code>、<code>TagSelect</code> 等）引用。</p><h2 id="模板简介" tabindex="-1">模板简介 <a class="header-anchor" href="#模板简介" aria-label="Permalink to &quot;模板简介&quot;">​</a></h2><p><code>tpl-react-admin-antd-pro</code> 保留 ant-design-pro 的完整页面、路由、资源与 mock；精确上游快照由模板的 <code>upstream.json</code> 记录。</p><p><code>tpl-vue2-admin-antd-pro</code> 来自 <code>vueComponent/ant-design-vue-pro</code> v3.0.4（MIT），保留 <code>views</code>、<code>router</code>、<code>store</code>、<code>api</code>、<code>mock</code>、<code>utils</code> 等宿主部分，把图表、列表页部件和弹窗 / 加载插件交给 <code>comps-vue2-antd-pro</code> 远程加载；依赖 <code>$store</code> / <code>$route</code> / <code>$t</code> 的 <code>GlobalHeader</code>、<code>MultiTab</code>、<code>Table</code>、<code>SelectLang</code>、<code>SettingDrawer</code> 仍留在模板内。上游原始栈为 vue-cli 5，接入时统一改为仓库 Vue 2 线的 vue-cli 4 与锁定版本。</p><h2 id="从原开源模板快速接入" tabindex="-1">从原开源模板快速接入 <a class="header-anchor" href="#从原开源模板快速接入" aria-label="Permalink to &quot;从原开源模板快速接入&quot;">​</a></h2><ul><li><strong>Vue 2 Pro</strong>：在自己的模板副本安装 Vue 2.7、匹配的 Ant Design Vue 1.x、HEL 核心和可安装的组件代理。按<a href="./../../guide/adapt-template.html">模板入口改造步骤</a>拆分启动代码；在预加载中指定你的 <code>hel-meta.json</code> 地址，进入业务入口后，从组件代理导入图表和页面部件。若上游页面都通过 <code>@/components</code> 导入，可在原目录的 <code>index.js</code> 中转出相同名称。保留依赖 store、路由和国际化的本地组件。</li><li><strong>React Pro</strong>：在 Umi 异步入口共享 React 运行时、预加载 UI 依赖，再进入业务。按模板的导入配置映射 Ant Design、Pro、图标和样式运行时；改造后打开列表、表单与图表，确认组件和主题一起生效。</li></ul><h2 id="vue-2-pro-的接入检查" tabindex="-1">Vue 2 Pro 的接入检查 <a class="header-anchor" href="#vue-2-pro-的接入检查" aria-label="Permalink to &quot;Vue 2 Pro 的接入检查&quot;">​</a></h2><p>在 Vue CLI 4 项目的 <code>transpileDependencies</code> 中包含 <code>@melt-js/libs-core</code>。使用组件包的公开入口。构建后试用图表、对话框和加载动画；如果插件导出缺失，请核对代理与托管组件是否来自同一版本。该模板使用 hash 路由，可直接验证静态子路径上的刷新行为。</p>',20)])])}const m=t(a,[["render",c]]);export{p as __pageData,m as default};
